<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Client\Domain;

use Civi\Lughauth\Features\OAuth\Authentication\Domain\ValueObject\ResponseType;
use Civi\Lughauth\Features\OAuth\Client\Domain\Exception\DynamicClientException;

/**
 * Domain service that checks the metadata of a dynamic registration or update (RFC 7591/7592)
 * against the tenant rules before anything is persisted (task 024).
 *
 * - Redirect URIs must have a scheme and never a script-capable one.
 * - Every grant type must be allowed by the rules (or the initial access token); the password
 *   grant also needs the explicit tenant permission.
 * - Every response type must be one the authorization endpoint issues (ResponseType::SUPPORTED,
 *   so no implicit) and be backed by a registered grant type.
 * - The token endpoint auth method must be supported by the server and allowed by the rules; a
 *   public client ("none") cannot use client_credentials or password.
 */
final class DcrMetadataPolicy
{
    /** URI schemes that are explicitly forbidden as redirect URIs for security reasons. */
    private const array FORBIDDEN_URI_SCHEMES = ['javascript', 'data', 'vbscript'];
    /**
     * Token endpoint auth methods a dynamic client can use. private_key_jwt also needs the client
     * keys (jwks or jwks_uri), which dynamic registration does not accept yet.
     */
    private const array SUPPORTED_AUTH_METHODS = ['client_secret_basic', 'client_secret_post', 'none'];
    /** Grant type that each response type part needs. */
    private const array RESPONSE_TYPE_GRANTS = [
        'code' => 'authorization_code',
        'token' => 'implicit',
        'id_token' => 'implicit',
    ];
    /** Grants that need a client able to keep a secret. */
    private const array CONFIDENTIAL_GRANTS = ['client_credentials', 'password'];

    /**
     * Throws a DynamicClientException (invalid_redirect_uri or invalid_client_metadata) for the
     * first rule the request breaks.
     */
    public function validate(DynamicClientRequest $request, DcrRegistrationRules $rules): void
    {
        foreach ($request->redirectUris as $uri) {
            $scheme = is_string($uri) ? strtolower((string) parse_url($uri, PHP_URL_SCHEME)) : '';
            if ($scheme === '' || in_array($scheme, self::FORBIDDEN_URI_SCHEMES, true)) {
                throw DynamicClientException::invalidRedirectUri(is_string($uri) ? $uri : '');
            }
        }

        $grantTypes = self::strings($request->grantTypes, 'grant_types');
        foreach ($grantTypes as $grantType) {
            if (!in_array($grantType, $rules->allowedGrantTypes, true)
                || ($grantType === 'password' && !$rules->allowPasswordGrant)
            ) {
                throw DynamicClientException::invalidClientMetadata("grant_type not allowed: {$grantType}");
            }
        }

        // An empty list is a client that never uses the authorization endpoint (e.g. M2M).
        foreach (self::strings($request->responseTypes, 'response_types', allowEmpty: true) as $responseType) {
            if (!ResponseType::fromString($responseType)->isSupported()) {
                throw DynamicClientException::invalidClientMetadata("response_type not supported: {$responseType}");
            }
            foreach (explode(' ', $responseType) as $part) {
                $needed = self::RESPONSE_TYPE_GRANTS[$part] ?? null;
                if ($needed === null || !in_array($needed, $grantTypes, true)) {
                    throw DynamicClientException::invalidClientMetadata("response_type not allowed: {$responseType}");
                }
            }
        }

        $method = $request->tokenEndpointAuthMethod;
        if (!in_array($method, self::SUPPORTED_AUTH_METHODS, true) || !in_array($method, $rules->allowedAuthMethods, true)) {
            throw DynamicClientException::invalidClientMetadata("token_endpoint_auth_method not allowed: {$method}");
        }
        if ($method === 'none' && array_intersect($grantTypes, self::CONFIDENTIAL_GRANTS) !== []) {
            throw DynamicClientException::invalidClientMetadata('A public client cannot use client_credentials or password');
        }
    }

    /**
     * @return string[]
     */
    private static function strings(array $values, string $field, bool $allowEmpty = false): array
    {
        if ($values === [] && !$allowEmpty) {
            throw DynamicClientException::invalidClientMetadata("{$field} must not be empty");
        }
        foreach ($values as $value) {
            if (!is_string($value) || $value === '') {
                throw DynamicClientException::invalidClientMetadata("{$field} must be a list of strings");
            }
        }
        return array_values($values);
    }
}
